;------------------------------------------------------------------------------; fichier.........: m-utils.asm; type fichier....: macros; Scripteur.......: Daniel Lafrance, Québec, canada.; version......: 0.0.1; revision.....: 20151126;------------------------------------------------------------------------------;------------------------------------------------------------------------------; Charge dans $YYXX le contenu de ladresse 16 bits donnée en paramètre.;------------------------------------------------------------------------------ldyxptr        .macro pointeur               php               ldy   \pointeur+1               ldx   \pointeur               plp               .endm;------------------------------------------------------------------------------; Charge dans $xxyy le contenu de ladresse 16 bits donnée en paramètre.;------------------------------------------------------------------------------ldxyptr        .macro pointeur               php               ldy   \pointeur               ldx   \pointeur+1               plp               .endm;------------------------------------------------------------------------------; Sauvegarde le contenu 16 bits $YYXX l'adresse donnée en paramètre.;------------------------------------------------------------------------------styxptr        .macro pointeur               sty   \pointeur+1               stx   \pointeur               .endm;------------------------------------------------------------------------------; Sauvegarde le contenu 16 bits $xxyy l'adresse donnée en paramètre.;------------------------------------------------------------------------------stxyptr        .macro pointeur               sty   \pointeur               stx   \pointeur+1               .endm;------------------------------------------------------------------------------; Charge le contenu 16 bits d'une case memoire dans $YYXX.;------------------------------------------------------------------------------ldyximm        .macro immval               php               ldy   #>\immval               ldx   #<\immval               plp               .endm;------------------------------------------------------------------------------; Charge le contenu 16 bits d'une case memoire dans $XXYY.;------------------------------------------------------------------------------ldxyimm        .macro xyimm               php               ldx   #>\xyimm               ldy   #<\xyimm               plp               .endm;------------------------------------------------------------------------------; Charge dans $AAXX le contenu de ladresse 16 bits donnée en paramètre.;------------------------------------------------------------------------------ldaxmem        .macro axadd               php               lda   \axadd+1 ;msb adr dans A.               ldx   \axadd   ;lsb adr dans X.               plp               .endm;------------------------------------------------------------------------------; Charge dans $AAXX un nombre 16 bits donnée en paramètre.;------------------------------------------------------------------------------ldaximm        .macro aximm               php               lda   #>\aximm ;MSB val dans a.               ldx   #<\aximm ;LSB val dans x.               plp               .endm;------------------------------------------------------------------------------; Charge dans zpage1 un nombre 16 bits donnée en paramètre.;------------------------------------------------------------------------------ptrtozp1       .macro immval               jsr   push               ldy   #>\immval ;MSB val dans y.               ldx   #<\immval ;LSB val dans x.               sty   zpage1+1               stx   zpage1               jsr   pop               .endm;------------------------------------------------------------------------------; Charge dans zpage2 un nombre 16 bits donnée en paramètre.;------------------------------------------------------------------------------ptrtozp2       .macro immval               jsr   push               ldy   #>\immval               ldx   #<\immval               sty   zpage2+1               stx   zpage2               jsr   pop               .endm;------------------------------------------------------------------------------; Affichage d'un caractere par kernal.;------------------------------------------------------------------------------outcar         .macro carno               php               pha               lda   #\carno               jsr   chrout               pla               plp               .endm        ;------------------------------------------------------------------------------; Affiche une chaine de caracteres parle kernal.;------------------------------------------------------------------------------outstr      .macro string            jsr   pushall            ldy   #>\string+1            ldx   #<\string            jsr   putsyx            jsr   popall            .endm;------------------------------------------------------------------------------; Affiche une chaine de caracteres par le kernal a la position (x,y).;------------------------------------------------------------------------------outstrxy    .macro string            jsr   push            ldx   \string            ldy   \string+1            jsr   gotoxy            ldy   #>\string+2            ldx   #<\string+2            jsr   putsyx            jsr   pop            .endm;------------------------------------------------------------------------------; Place sur la pile tous les registres.;------------------------------------------------------------------------------mpushr  .macro            php            pha        txa            pha        tya            pha        .endm;------------------------------------------------------------------------------; Recupere les registres de la pile.;------------------------------------------------------------------------------mpopr   .macro            pla        tay            pla        tax            pla            plp        .endm        ;------------------------------------------------------------------------------; Initialise les donneed de la fonction; loop.;------------------------------------------------------------------------------setloop .macro lcount            pha        lda  #<\lcount        sta  loopcount        lda  #>\lcount        sta  loopcount+1            pla        .endm;------------------------------------------------------------------------------; Permet les changement de police avec ; [C=]+[SHIFT].;------------------------------------------------------------------------------enable         .macro                   php                   pha               lda  #$09                   jsr  $ffd2                   pla                   plp               .endm;------------------------------------------------------------------------------; Inhibe les changement de police avec ; [C=]+[SHIFT].;------------------------------------------------------------------------------disable        .macro                   php                   pha               lda  #$08                   jsr  $ffd2                   pla                   plp               .endm;------------------------------------------------------------------------------; Selectionne le jeu de caracteres; minuscule.;------------------------------------------------------------------------------tolower        .macro                   php                   pha               lda  #14                   jsr  $ffd2                   pla                   plp               .endm;------------------------------------------------------------------------------; Selectionne le jeu de caracteres; majuscule.;------------------------------------------------------------------------------toupper        .macro                   php                   pha               lda  #b_uppercase                   jsr  $ffd2                   pla                   plp               .endm;------------------------------------------------------------------------------; Change la couleur de la bordure.;------------------------------------------------------------------------------changebord     .macro c                   php                   pha               lda  #\c               sta  $d020                   pla                   plp               .endm;------------------------------------------------------------------------------; Change la couleur de l'arriere plan; de l'ecran.;------------------------------------------------------------------------------changeback     .macro c                   php                   pha               lda  #\c               sta  $d021                   pla                   plp               .endm;------------------------------------------------------------------------------; Sélectionne les couleurs naturelle du; commodore 64.;------------------------------------------------------------------------------c64color       .macro                   jsr  push               #changebord cbleupale               #changeback cbleu               #color cbleupale                   jsr  pop               .endm;------------------------------------------------------------------------------; Sélectionne mes couleurs préférées.;------------------------------------------------------------------------------mescol         .macro                   jsr  push               #changebord cvert               #changeback cbleu               #color cblanc                   jsr  pop               .endm;------------------------------------------------------------------------------; Couleurs Commodore 64 + texte blanc;------------------------------------------------------------------------------c64col         .macro                   jsr  push               #changebord cbleupale               #changeback cbleu               #color cblanc                   jsr  pop               .endm;------------------------------------------------------------------------------; Sélectionne les couleurs naturelle du; commodore Vic 20.;------------------------------------------------------------------------------v20col         .macro                   jsr  push               #changebord ccyan               #changeback cblanc               #color cbleu                   jsr  pop               .endm;------------------------------------------------------------------------------; Sélectionne un jeu de couleurs grises;------------------------------------------------------------------------------griscol        .macro                   jsr  push               #changebord cgrismoyen               #changeback cgrisfonce               #color cgrispale                   jsr  pop               .endmmycolor        .macro               jsr  push               #changebord cvert               #changeback cbleu               #color cblanc               jsr  pop               .endmscrcolors      .macro fg, bg                        pha               lda #(\bg*16+(\fg|8))               sta  vicscrbrd               pla               .endmgraycolor      .macro               jsr  push               #changebord cgrismoyen               #changeback cgrisfonce               #color cgrispale               jsr  pop               .endm;------------------------------------------------------------------------------; Place une adresse dans ZP1.;------------------------------------------------------------------------------setzpage1      .macro addr                   pha               lda  \addr               sta  $fb               lda  \addr+1               sta  $fc                   pla               .endm;------------------------------------------------------------------------------; Place une adresse dans ZP1.;------------------------------------------------------------------------------setzpage2      .macro addr                   pha               lda  \addr               sta  $fd               lda  \addr+1               sta  $fe                   pla               .endm;------------------------------------------------------------------------------; Deplace le curseur a la position ; (x,y).;------------------------------------------------------------------------------locate      .macro x,y                jsr push            ldx #\x            ldy #\y                jsr gotoxy                jsr pop            .endm;------------------------------------------------------------------------------; Sélectionne la couleur du texte.;------------------------------------------------------------------------------color          .macro    col                   pha               lda  #\col               sta  bascol                   pla               .endm;------------------------------------------------------------------------------; Affiche une chaine pointée par $YYXX.;------------------------------------------------------------------------------print          .macro strptr                   jsr  push               ldx  #<\strptr               ldy  #>\strptr                   jsr  putsyx                   jsr  pop               .endm;------------------------------------------------------------------------------; Affiche une chaine pointée par $YYXX; suivie par une crlf.;------------------------------------------------------------------------------println        .macro strptr                   jsr  push               ldx  #<\strptr               ldy  #>\strptr                   jsr  putsyx               lda  #$0d                   jsr  chrout                   jsr  pop               .endm;------------------------------------------------------------------------------; Affiche une chaine pointée par $YYXX; à la position X,Y.;------------------------------------------------------------------------------print_xy        .macro x,y,strptr                    jsr  push                ldy  #\x                ldx  #\y                clc                    jsr  plot                ldx  #<\strptr                 ldy  #>\strptr                    jsr  putsyx                    jsr  pop                .endm;------------------------------------------------------------------------------; Affiche une chaine pointée par $YYXX; à la position X,Y dans ka couleur C.;------------------------------------------------------------------------------print_cxy       .macro c,x,y,strptr                    jsr push                lda bascol                    pha                 lda #\c                sta bascol                ldy #\x                ldx  #\y                clc                    jsr  plot                ldx  #<\strptr                 ldy  #>\strptr                    jsr  putsyx                    pla                sta  bascol                    jsr  pop                .endm;------------------------------------------------------------------------------; Affiche une chaine pointée par $YYXX; à la position X,Y.;------------------------------------------------------------------------------printxy        .macro strptr                   jsr  push               ldx  #<\strptr                ldy  #>\strptr                   jsr  putsxy                   jsr  pop               .endm;------------------------------------------------------------------------------; Affiche une chaine pointée par $YYXX; à la position X,Y dans ka couleur C.;------------------------------------------------------------------------------printcxy       .macro strptr                   jsr  push               ldx  #<\strptr                ldy  #>\strptr                   jsr  putscxy                   jsr  pop               .endm;------------------------------------------------------------------------------; Affiche un texte précédé d'un préfixe;------------------------------------------------------------------------------printfmt       .macro prefix, strptr                   jsr  push               lda  #\prefix                   jsr  chrout               #print \strptr                   jsr  pop               .endm;------------------------------------------------------------------------------; Affiche une chaine pointée par $YYXX; à la position X,Y.;------------------------------------------------------------------------------printpos       .macro x,y,strptr                   jsr  push               #locate \x,\y               #print \strptr                   jsr  pop               .endm;------------------------------------------------------------------------------; Affiche un texte précédé d'un préfixe; à la position X,Y.;------------------------------------------------------------------------------printfmtxy     .macro x,y,prefix,strptr                   jsr  push               #locate \x,\y               #printfmt \prefix,\strptr                   jsr  pop               .endm;------------------------------------------------------------------------------; Affiche un mot 16 bits en binaire ; issue d'une case memoire.;------------------------------------------------------------------------------printval16bin  .macro adresse                   jsr  pushall               lda  #<\adresse               sta  $fb               lda  #>\adresse               sta  $fb+1               ldy  #$01                lda  ($fb),y                   jsr  atobin               #printfmt "%", abin               dey               lda  ($fb),y                   jsr  atobin               #print abin                   jsr  popall               .endm;------------------------------------------------------------------------------; Affiche un mot 16 bits en binaire ; issue d'une case memoire (indirect).;------------------------------------------------------------------------------printptr16bin  .macro adresse                   jsr  pushall               lda  #>\adresse+1               lda  #>\adresse+1                   jsr  atobin               #printfmt "%", abin               lda  #<\adresse                   jsr  atobin               #printfmt "", abin                   jsr  popall               .endmprintwordbin   .macro adresse               jsr  pushall               lda  #<\adresse               sta  $fb               lda  #>\adresse               sta  $fb+1               ldy  #$01                lda  ($fb),y               jsr  atobin               #printfmt "%", abin               dey               lda  ($fb),y               jsr  atobin               #print abin               jsr  popall               .endm;------------------------------------------------------------------------------